#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-11

# strict-mode: opt-out this harness counts failures and prints a summary, so
# `-e` would abort on the first failing assertion. `set -uo pipefail` below.
#
# =============================================================================
# The test runner must label tests by path, not basename (#4050)
# =============================================================================
# Three different files are named test-fault-arms.sh:
#
#   tests/ci/test-fault-arms.sh
#   tests/manifests/test-fault-arms.sh
#   tests/plugins/test-fault-arms.sh
#
# The Manifests & Schemas job runs all three directories, so with a basename
# label its log carries three identical `[RUN] test-fault-arms.sh` lines from
# three different files with three different gate lists, and the failure
# summary names one without saying which.
#
# That is not cosmetic. Triaging a real review block, a first-match grep on the
# job log found the tests/manifests one PASSING in 1s, its gate list did not
# contain the failing gate, and the obvious conclusion was that the gate had
# never run. The actual failure was the tests/ci one, 11 seconds later in the
# same log. First-match reads green while a different file of the same name is
# red, and both a human and an agent triage from that log.
#
# This pins the label FORMAT rather than today's duplicate, so a future
# duplicate is distinguishable the day it appears, with no rule to remember.
#
# Assertions grep a FILE, never a pipe. `printf ... | grep -q` early-exits on
# match and SIGPIPEs the producer; under `pipefail` that 141 propagates and
# flips the enclosing `if` non-deterministically (#603).
# =============================================================================

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; NC=$'\033[0m'
PASS=0; FAIL=0
pass() { echo "  ${GREEN}PASS${NC} $1"; PASS=$((PASS + 1)); }
fail() { echo "  ${RED}FAIL${NC} $1"; FAIL=$((FAIL + 1)); }

echo "=========================================="
echo "  runner labels tests by path (#4050)"
echo "=========================================="

TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork-label.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT

# Two directories, ONE filename. This is the shape that makes a basename label
# ambiguous, reproduced in miniature so the assertion does not depend on
# test-fault-arms.sh remaining the repo's duplicate.
# The runner takes ONE directory and `find`s it recursively, so the twins go in
# two subdirectories of a single suite rather than in two arguments.
mkdir -p "$TMP/suite/alpha" "$TMP/suite/beta"
printf '#!/usr/bin/env bash\nexit 0\n' > "$TMP/suite/alpha/test-twin.sh"
printf '#!/usr/bin/env bash\nexit 1\n' > "$TMP/suite/beta/test-twin.sh"

RUNNER="$REPO_ROOT/scripts/ci/run-tests.sh"
OUT="$TMP/runner-output.txt"

if [[ ! -f "$RUNNER" ]]; then
  fail "runner not found at $RUNNER"
else
  # The beta twin fails ON PURPOSE, so a non-zero status here is the expected
  # outcome and carries no information. The assertion is on the TEXT emitted.
  # silent: known-noise a failing subject is this test's own fixture
  ( cd "$TMP" && bash "$RUNNER" suite ) > "$OUT" 2>&1 || true
  # silent: known-noise colour stripping is cosmetic; an unstripped file still
  # satisfies the greps below, so a sed failure must not abort the run
  sed -i'' -e 's/\x1b\[[0-9;]*m//g' "$OUT" 2>/dev/null || true

  # Anti-vacuity first: if the runner emits nothing, every grep below goes quiet
  # and a weaker version of this test would read that as a pass.
  if [[ -s "$OUT" ]]; then
    pass "the runner produced output to assert against"
  else
    fail "the runner produced no output; the assertions below prove nothing"
  fi

  if grep -q 'suite/alpha/test-twin.sh' "$OUT" && grep -q 'suite/beta/test-twin.sh' "$OUT"; then
    pass "both same-named tests are reported with their directory"
  else
    fail "the runner did not distinguish two same-named tests"
    grep -E 'test-twin' "$OUT" | sed 's/^/         /'
  fi

  # The failure summary is what a reader sees first, so it has to disambiguate
  # too. A [RUN] line carrying the path while the summary still said
  # `test-twin.sh` would leave triage exactly as ambiguous as before.
  #
  # Anchored to the "Failed tests:" block rather than grepping the whole file.
  # A bare grep here would be satisfied by the [RUN] and [FAIL] lines the
  # previous assertion already covers, so it would restate that check while
  # claiming to test the summary: a passing assertion that proves nothing.
  SUMMARY="$TMP/summary.txt"
  # silent: known-noise sed prints nothing when the block is absent, which the
  # emptiness check below reports as the failure it is
  sed -n '/Failed tests:/,$p' "$OUT" > "$SUMMARY" 2>/dev/null || true
  if [[ ! -s "$SUMMARY" ]]; then
    fail "no 'Failed tests:' block in the runner output; cannot check the summary"
  elif grep -q 'suite/beta/test-twin.sh' "$SUMMARY"; then
    pass "the failure summary block names the failing file's path"
  else
    fail "the failure summary block does not name the path of the failing file"
    sed 's/^/         /' "$SUMMARY" | head -5
  fi
fi

echo "=========================================="
echo "  Passed: $PASS  Failed: $FAIL"
echo "=========================================="
[[ $FAIL -eq 0 ]]
